composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
    depends_on:
      - {{serviceName}}-db
{{ports}}
{{volumes}}
{{environment}}
  {{serviceName}}-db:
    image: postgres:16-alpine
    container_name: {{containerName}}-db
    restart: unless-stopped
    volumes:
      - {{env.JELLYSTAT_DB_VOLUME}}
    environment:
      POSTGRES_USER: {{env.POSTGRES_USER}}
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
